window.AULAS["imuno-thiago-10"] = {"subtitulo": "Imunologia dos tumores e imunoterapia", "pdf": "pdf/thiago/aula-10.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "pdf"], "fontes": ["Aula 10 · Imunologia dos Tumores (Prof. Dr. Thiago Corrêa)", "Abbas, Lichtman e Pillai (2019); Boon et al. (2006); Khalil et al. (2016); Jorge (2019) (citados nos slides)"], "resumo": [{"titulo": "1. Origem dos antígenos tumorais", "pontos": [{"t": "Neoantígenos", "sub": ["A maioria é gerada por genes mutantes em clones tumorais; células normais não expressam esses peptídeos (slide 3)."]}, {"t": "Vírus oncogênicos", "sub": ["Proteínas estranhas de vírus como HPV e EBV; a resposta é essencialmente antiviral (slide 4)."]}, {"t": "Alteração epigenética", "sub": ["Metilação de CpG marca genes silenciados (slide 5).", "CEA (cólon, pâncreas, estômago, mama) e alfa-fetoproteína (fígado, células germinativas) são expressos em tumores e no desenvolvimento (slide 6)."]}, {"t": "Expressão aberrante", "sub": ["Amplificação gênica leva à superexpressão, como HER2/neu (slide 7)."]}]}, {"titulo": "2. Defesa antitumoral", "pontos": [{"t": "Linfócitos T CD8+", "sub": ["Principal mecanismo: eliminação de células tumorais por CTLs (slide 9).", "Th1 intensifica a resposta de CD8+ e ativa macrófagos (slide 9)."]}, {"t": "Células NK", "sub": ["NK destroem muitos tumores; perda de MHC-I remove o sinal inibitório e torna a célula alvo (slide 11).", "ADCC: NK ativada destrói células cobertas por anticorpos antitumorais (slide 12)."]}, {"t": "Imunovigilância e imunoedição", "sub": ["Imunovigilância: o sistema reconhece e elimina células transformadas (estudo dirigido, slide 25).", "Modelo de Dunn, Old e Schreiber (2002): eliminação, equilíbrio e escape. O PDF da aula cita a imunovigilância; as três fases são do modelo de imunoedição (fonte: Dunn et al., Nature Immunology, 2002)."]}]}, {"titulo": "3. Escape tumoral e macrófagos", "pontos": [{"t": "Imunoevasão", "sub": ["Ligantes de receptores inibitórios, como PD-L1 para PD-1, e citocinas imunossupressoras (slide 15).", "Perda de MHC-I impede a apresentação de antígeno tumor-específico (slide 16)."]}, {"t": "Macrófagos", "sub": ["Inibem ou promovem o tumor: pró-inflamatórios (TNF, IL-1, IL-6) combatem; anti-inflamatórios (IL-10, TGF-beta) favorecem crescimento e angiogênese (slide 13)."]}]}, {"titulo": "4. Imunoterapia e checkpoints", "pontos": [{"t": "Receptores inibitórios", "sub": ["CTLA-4 liga-se a CD80/CD86 e inibe a célula T; seu bloqueio intensifica a resposta antitumoral (slide 18).", "PD-1, expresso em T, liga-se a PD-L1 em células tumorais; o bloqueio com anticorpos intensifica a eliminação e contém cânceres avançados (slide 19)."]}, {"t": "Terapia celular", "sub": ["CAR-T: células T com receptores quiméricos contra antígenos tumorais (slides 20 e 21).", "Caso de remissão após terapia celular em estudo no SUS, citado no slide 22."]}, {"t": "Anticorpos monoclonais", "sub": ["Intensificam mecanismos efetores, interferem na sinalização de crescimento ou levam quimioterápico ao tumor (slide 23)."]}]}, {"titulo": "5. Para prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Origem de cada tipo de antígeno tumoral (mutação, vírus, epigenética, superexpressão).", "Função de CTLA-4 × PD-1, e por que o bloqueio ajuda.", "Papel de NK com perda de MHC-I e ADCC."]}]}], "glossario": [{"termo": "Neoantígeno", "tecnica": "Origem dos antígenos tumorais", "definicao": "Antígeno novo produzido por genes mutantes nas células tumorais.", "slide": 3}, {"termo": "CEA e alfa-fetoproteína", "tecnica": "Antígenos por alteração epigenética", "definicao": "Antígenos expressos em gametas e trofoblasto, reativados em alguns cânceres.", "slide": 6}, {"termo": "HER2/neu", "tecnica": "Expressão aberrante", "definicao": "Proteína superexpressa por amplificação gênica em alguns tumores.", "slide": 7}, {"termo": "ADCC", "tecnica": "Defesa antitumoral", "definicao": "Citotoxicidade celular dependente de anticorpo: NK destrói células cobertas por anticorpos.", "slide": 12}, {"termo": "PD-1 / PD-L1", "tecnica": "Imunoterapia com receptores inibitórios", "definicao": "Receptor inibitório de T (PD-1) e seu ligante (PD-L1), usados como alvos de bloqueio.", "slide": 19}, {"termo": "CTLA-4", "tecnica": "Imunoterapia com receptores inibitórios", "definicao": "Receptor inibitório de T cujo bloqueio intensifica a resposta antitumoral.", "slide": 18}, {"termo": "CAR-T", "tecnica": "Imunoterapia celular", "definicao": "Células T modificadas para expressar receptores quiméricos contra antígenos tumorais.", "slide": 21}], "caso": {"titulo": "Caso: melanoma avançado e escolha da imunoterapia", "perfil": "Imunoevasão e alvos de imunoterapia.", "etapas": [{"titulo": "Etapa 1: escape tumoral", "texto": "Homem de 60 anos com melanoma metastático. A biópsia mostra alta expressão de PD-L1 nas células tumorais, e os linfócitos T infiltrantes estão inibidos. A equipe discute um bloqueador de receptor inibitório.", "perguntas": [{"pergunta": "Qual mecanismo de escape tumoral é o mais compatível com esse achado, segundo a aula?", "alts": ["Produção de ligantes como PD-L1 para receptores inibitórios das células T", "Perda total de antígenos tumorais, sem reconhecimento possível", "Estímulo de linfócitos B que produzem IgE contra o tumor", "Ativação de mastócitos que liberam histamina no microambiente", "Excesso de MHC de classe I, que ativa as células NK inibidas"], "erradas": ["A aula descreve escape por ligantes inibitórios, não por perda total de antígenos.", "IgE e mastócitos são mecanismos da hipersensibilidade tipo I.", "Excesso de MHC de classe I inibe NK, e não as ativa.", "Aumento de MHC-I não é o escape descrito para PD-L1."], "justificativa": "Células tumorais produzem ligantes, como PD-L1, para receptores inibitórios das células T (slide 15)."}]}, {"titulo": "Etapa 2: leucemia refratária", "texto": "Paciente com leucemia refratária a várias linhas de tratamento. A equipe considera terapia com células T geneticamente modificadas para reconhecer um antígeno tumoral.", "perguntas": [{"pergunta": "Qual é a terapia descrita, segundo a aula?", "alts": ["CAR-T, células T com receptores quiméricos contra antígenos tumorais", "Transfusão de linfócitos B de memória com IgE específica", "Vacina conjugada contra antígenos tumorais de polissacarídeo", "Transplante alogênico de CTH sem modificação das células T", "Anticorpo anti-CTLA-4 administrado em dose única por via oral"], "erradas": ["Linfócitos B de memória com IgE não são a terapia descrita.", "Vacina conjugada é de prevenção infecciosa, não de terapia celular tumoral.", "Transplante de CTH não envolve receptores quiméricos.", "Anticorpo anti-CTLA-4 é administrado por via intravenosa, não oral."], "justificativa": "A terapia celular com CAR-T usa células T com receptores quiméricos contra antígenos tumorais (slides 20 e 21)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um tumor é analisado e a maioria dos antígenos reconhecidos vem de genes com mutação somática. Como esses antígenos são classificados pela aula?", "alternativas": ["Antígenos virais, produzidos por vírus oncogênicos integrados", "Antígenos epigenéticos, com silenciamento por metilação de CpG", "Neoantígenos, produzidos por genes mutantes em clones tumorais", "Autoantígenos normais, expressos também em tecidos adultos", "Antígenos de superexpressão, por amplificação gênica"], "gabarito": "C", "justificativa": "A maioria dos antígenos tumorais é neoantígeno gerado por genes mutantes (Aula 10, slide 3).", "tecnica": "Neoantígenos", "slide": 3, "pdf": "pdf/thiago/aula-10.pdf"}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um antígeno tumoral é expresso em gametas e trofoblasto, e também em cânceres de cólon. Qual mecanismo de origem a aula atribui a isso?", "alternativas": ["Mutação pontual gerando neoepítopo", "Alteração epigenética de genes silenciados", "Infecção viral com proteína estranha", "Amplificação gênica levando à superexpressão", "Perda de MHC de classe I na superfície"], "gabarito": "B", "justificativa": "CEA e alfa-fetoproteína são expressos em gametas, trofoblastos e cânceres por alteração epigenética (Aula 10, slides 5 e 6).", "tecnica": "Alteração epigenética", "slide": 6, "pdf": "pdf/thiago/aula-10.pdf"}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Qual é o papel da metilação do DNA nos genes, segundo a aula, e onde ela ocorre?", "alternativas": ["Ativa genes amplificados, em sequências de MHC", "Marca genes silenciados, em CpG", "Converte DNA em RNA mensageiro nas células NK", "Remove o grupo fosfato das histonas em genes de citocinas", "Atua apenas nos genes de MHC de classe II"], "gabarito": "B", "justificativa": "A metilação ocorre em dinucleotídeos CpG e é marca de genes silenciados (Aula 10, slide 5).", "tecnica": "Metilação do DNA", "slide": 5, "pdf": "pdf/thiago/aula-10.pdf"}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um tumor de mama superexpressa uma proteína por amplificação gênica. Qual exemplo a aula dá para esse tipo de antígeno?", "alternativas": ["CEA", "Alfa-fetoproteína", "HER2/neu", "Citocromo c", "Histona H3"], "gabarito": "C", "justificativa": "Genes amplificados levam à superexpressão, como HER2/neu (Aula 10, slide 7).", "tecnica": "Expressão aberrante", "slide": 7, "pdf": "pdf/thiago/aula-10.pdf"}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Qual é o principal mecanismo imunológico de eliminação de células tumorais, e qual subpopulação T auxilia esse mecanismo, segundo a aula?", "alternativas": ["Mastócitos eliminam; Th2 suprime a resposta de CD8+", "Treg elimina; Th17 intensifica a resposta de NK", "Neutrófilos eliminam; Tfh produz IgE contra o tumor", "NK elimina; Treg ativa macrófagos M2", "CTLs CD8+ eliminam as células tumorais"], "gabarito": "E", "justificativa": "A eliminação por CTLs CD8+ é o principal mecanismo; Th1 intensifica a resposta CD8+ (Aula 10, slide 9).", "tecnica": "Defesa antitumoral", "slide": 9, "pdf": "pdf/thiago/aula-10.pdf"}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um tumor perde MHC de classe I. Qual consequência a aula descreve para a célula NK, e por quê?", "alternativas": ["NK é inibida, porque a ausência de MHC-I aumenta o sinal inibitório", "NK não reage, porque NK só reconhece MHC de classe II", "NK produz MHC-I em resposta e se torna inativa", "NK é ativada, porque a ausência de MHC-I remove o sinal inibitório", "NK converte-se em Treg, que protege o tumor"], "gabarito": "D", "justificativa": "Células NK são inibidas pelo MHC-I; sem ele, a NK é ativada (Aula 10, slide 11).", "tecnica": "Células NK", "slide": 11, "pdf": "pdf/thiago/aula-10.pdf"}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Uma célula NK destrói uma célula tumoral coberta por anticorpos antitumorais. Como a aula chama esse mecanismo?", "alternativas": ["Apresentação cruzada por MHC de classe I, com CD8+", "Neutralização por IgA secretora", "Opsonização por complemento sem NK", "ADCC, citotoxicidade dependente de anticorpo", "Imunoedição por escape tumoral"], "gabarito": "D", "justificativa": "ADCC é a destruição por NK ativada de células cobertas por anticorpos (Aula 10, slide 12).", "tecnica": "ADCC", "slide": 12, "pdf": "pdf/thiago/aula-10.pdf"}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Quais são os mecanismos de escape tumoral citados na aula, além da perda de MHC-I?", "alternativas": ["Ligantes como PD-L1 e citocinas supressoras", "Produção de IgE contra CD4 e perda de linfócitos B", "Expressão de CD80 em excesso e aumento de Treg apenas", "Produção de histamina e bloqueio de mastócitos", "Secreção de superóxido e inativação de NK"], "gabarito": "A", "justificativa": "Células tumorais produzem ligantes como PD-L1 e citocinas imunossupressoras (Aula 10, slide 15).", "tecnica": "Imunoevasão", "slide": 15, "pdf": "pdf/thiago/aula-10.pdf"}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Os macrófagos podem favorecer ou inibir o tumor. Quais citocinas a aula associa ao perfil anti-inflamatório que favorece o crescimento?", "alternativas": ["TNF e IL-1", "IL-10 e TGF-beta", "IFN-gama e IL-12", "IL-17 e IL-23", "IL-2 e IL-15"], "gabarito": "B", "justificativa": "IL-10 e TGF-beta são anti-inflamatórias e associadas à promoção tumoral (Aula 10, slide 13).", "tecnica": "Macrófagos no tumor", "slide": 13, "pdf": "pdf/thiago/aula-10.pdf"}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Qual é o efeito do bloqueio de CTLA-4 e qual molécula CTLA-4 se liga, segundo a aula?", "alternativas": ["Reduz a resposta antitumoral; liga-se a PD-L1", "Ativa linfócitos B; liga-se a IgE", "Intensifica a fagocitose; liga-se ao MHC-II", "Induz apoptose de NK; liga-se a CD40", "Intensifica a resposta antitumoral"], "gabarito": "E", "justificativa": "CTLA-4 inibe a célula T ao ligar CD80 e CD86; seu bloqueio intensifica a resposta antitumoral (Aula 10, slides 18 e 25).", "tecnica": "Checkpoint CTLA-4", "slide": 18, "pdf": "pdf/thiago/aula-10.pdf"}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um paciente com câncer avançado recebe anticorpo contra PD-1 ou PD-L1. Qual é a finalidade descrita na aula?", "alternativas": ["Intensificar a eliminação tumoral por T", "Substituir a quimioterapia por bloqueio de IgE", "Impedir a formação de células de memória no paciente", "Aumentar a histamina dos mastócitos do tumor", "Induzir tolerância central no timo do paciente"], "gabarito": "A", "justificativa": "O bloqueio de PD-1 ou PD-L1 intensifica a eliminação tumoral e contém a progressão (Aula 10, slide 19).", "tecnica": "Checkpoint PD-1 e PD-L1", "slide": 19, "pdf": "pdf/thiago/aula-10.pdf"}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Qual é a característica das células CAR-T, segundo a aula?", "alternativas": ["Células NK ativadas por IgE contra antígenos tumorais", "Linfócitos B de memória que produzem IgA", "Células dendríticas com MHC de classe II inibido", "Células T com receptores quiméricos", "Macrófagos que produzem IL-10"], "gabarito": "D", "justificativa": "CAR-T são células T com receptores quiméricos contra antígenos tumorais (Aula 10, slide 21).", "tecnica": "CAR-T", "slide": 21, "pdf": "pdf/thiago/aula-10.pdf"}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Anticorpos monoclonais antitumorais atuam de três maneiras, segundo a aula. Qual delas está descrita corretamente?", "alternativas": ["Destroem o DNA tumoral diretamente, sem efeito imune", "Substituem os linfócitos T na defesa antitumoral", "Intensificam efetores e bloqueiam crescimento", "Bloqueiam a produção de MHC de classe I em todas as células", "Ativam apenas mastócitos, com liberação de histamina"], "gabarito": "C", "justificativa": "Monoclonais intensificam efetores, interferem na sinalização de crescimento e podem levar quimioterápico (Aula 10, slide 23).", "tecnica": "Monoclonais", "slide": 23, "pdf": "pdf/thiago/aula-10.pdf"}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Qual é o nome do processo de vigilância imune contra células transformadas, citado no estudo dirigido da aula?", "alternativas": ["Imunovigilância", "Imunodeficiência", "Imunorregulação", "Imunossensibilização", "Imunoterapia de bloqueio"], "gabarito": "A", "justificativa": "A aula cita imunovigilância no estudo dirigido (Aula 10, slide 25). As fases eliminação, equilíbrio e escape pertencem ao modelo de imunoedição, que o PDF não detalha.", "tecnica": "Imunovigilância", "slide": 25, "pdf": "pdf/thiago/aula-10.pdf"}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Além dos CTLs CD8+, quais células de defesa a aula menciona como participantes da resposta antitumoral?", "alternativas": ["Mastócitos e basófilos, com IgE antitumoral", "Neutrófilos e eosinófilos, com IgA secretora", "Células Treg e linfócitos B naive", "Plaquetas e células endoteliais", "NK e Th1, com macrófagos"], "gabarito": "E", "justificativa": "A aula cita NK, Th1 (que ativa macrófagos e CD8+) e macrófagos na defesa antitumoral (Aula 10, slides 9, 11 e 13).", "tecnica": "Células da defesa antitumoral", "slide": 9, "pdf": "pdf/thiago/aula-10.pdf"}], "id": "imuno-thiago-10", "titulo": "Aula 10", "voltar": {"href": "#/agressao/thiago", "texto": "Professor Thiago"}, "manobras": [], "imagens": [], "casos_extremos": []};
